public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    if (u == null) {
        return pathSegments;
    }

    String path = decode ? u.getPath() : u.getPath().encode(StandardCharsets.UTF_8);
    Pattern pattern = Pattern.compile("/");
    Matcher matcher = pattern.matcher(path);

    while (matcher.find()) {
        pathSegments.add(new PathSegmentImpl(matcher.group(), !(decode ? matcher.start() > 0 : false)));
    }

    if (decode && pathSegments.size() > 0 && pathSegments.get(0).isAbsolutePath()) {
        PathSegmentImpl firstSegment = pathSegments.remove(0);
        firstSegment.setAbsolutePath(false);
        pathSegments.add(0, firstSegment);
    }

    return pathSegments;
}

